	int bfs(int n) {
		if (isEndNode(n)) {
			visited[n] = true;
			try {
				if (allVisited()) {
					return 1;
				} else {
					return 0;
				}
			} finally {
				visited[n] = false;
			}
		}

		visited[n] = true;

		int ans = 0;
		for (int x : g.get(n)) {
			if (!visited[x]) {
				ans += bfs(x);
