    public void partialUpdateAndWarshallFloyd(long[][] edges, int x, int y, long w) {
        int n = edges.length;
        if (edges[x][y] > w)
            edges[x][y] = edges[y][x] = w;
        int[] l = {x, y};
        for (int k : l) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (edges[i][j] > edges[i][k] + edges[k][j]) {
                        edges[i][j] = edges[i][k] + edges[k][j];
                    }
                }
            }
        }
    }

    public long[][] createGraph(int n, int[][] edges) {
        long[][] graph = new long[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(graph[i], CONST_INF);
            graph[i][i] = 0;
        }
        int m = edges.length;
        for (int i = 0; i < m; i++) {
            int f = edges[i][0] - 1;
            int t = edges[i][1] - 1;
            long cost = edges[i][2];
            graph[f][t] = cost;
            graph[t][f] = cost;
        }
        return graph;
    }

    public long[][] warshallFloyd(int n, int[][] edges) {
        long[][] graph = createGraph(n, edges);
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    graph[i][j] = Math.min(graph[i][j], graph[i][k] + graph[k][j]);
                }
            }
        }
        return graph;
    }

