        boolean allVisited = true;
        for (int i = 0; i < N; i++) {
            if (!visited[i]) {
                allVisited = false;
            }
        }
        if (allVisited) {
            return 1;
        }
        int ret = 0;
        for (int i = 0; i < N; i++) {
            if (!graph[v][i]) continue;
            if (visited[i]) continue;

            visited[i] = true;
            ret += dfs(i, N, visited, graph);
            visited[i] = false;
        }
        return ret;
    }
