	 */
	private static int check(int p, int k, int[] w, int n) {
		int i = 0;
		// truckの数だけループ
		for (int j = 0; j < k; j++) {
			// max積載量になるまで
			int internalCapacity = 0;
			while (internalCapacity + w[i] <= p) {
				// 内容量を増やす
				internalCapacity += w[i];
				i++;

				// 全ての積載量を積むことができた場合
				if (i == n) {
					return n;
				}
			}
		}
		return i;
	}

