    private int bs(int c, int[] l) {
        int left = -1;
        int right = l.length;
        while (right - left > 1) {
            int mid = left + (right - left) / 2;
            if (c <= l[mid])
                right = mid;
            else
                left = mid;
        }
        return left;
    }


