					parent[b] += parent[a];
					parent[a] = b;
					return b;
				}
				parent[a] += parent[b];
				parent[b] = a;
				return a;
			}

			public boolean isSame(int a, int b) {
				return getLeader(a) == getLeader(b);
			}

