	public void solve()
	{
		int l = 1;
		int r = 10000 * 100000 + 1;
		int m = (r + l) / 2;
		int P = m;

		while(r - l > 1)
		{
			boolean valid = validate(m, n, k, wi);

			if(valid)
			{
				r = P = m;
			}
			else
			{
				l = m;
			}

			m = (r + l) / 2;
		}

		if(validate(m, n, k, wi)) P = m;

		System.out.println(P);
	}

	private boolean validate(final int P, final int n, final int k, final int[] wi)
	{
		int index = 0;

		for(int i=0; i < k; i++)
		{
			int sum = 0;

			while(sum + wi[index] <= P)
			{
				sum += wi[index++];

				if(index == n) return true;
