    static public boolean carry(int P, int k, int n) {
        if(P == 0) {
            return false;
        }
        int j = 0;
        for(int i = 0; i < k; i++) {
            int s = 0;
            while(s + W[j] <= P) {
                s += W[j];
                j++;
                if(j == n) return true;
            }
