public void solve() {
	int num = ni();
	int query = ni();
	UnionFind uf = new UnionFind(num);
	for(int q = 0; q < query; q ++) {
		if(ni() == 0) uf.unite(ni(), ni());
		else prtln(uf.same(ni(), ni()) ? 1 : 0);
	}
}

class UnionFind { // N=numNode
	int num;
	int parentOrSize[];

	UnionFind(int num) { // O(N)
		this.num = num;
		parentOrSize = new int[num];
		fill(parentOrSize, -1);
	}

	int unite(int x, int y) { // O(ﾎｱ(N))
		if(x < 0 || x >= num) throw new IndexOutOfBoundsException("x="+x);
		if(y < 0 || y >= num) throw new IndexOutOfBoundsException("y="+y);
		int xRoot = root(x);
		int yRoot = root(y);
		if(xRoot == yRoot) return xRoot;
		if(parentOrSize[yRoot] <= parentOrSize[xRoot]) {
			parentOrSize[yRoot] += parentOrSize[xRoot];
			parentOrSize[xRoot] = yRoot;
			return yRoot;
		}else {
			parentOrSize[xRoot] += parentOrSize[yRoot];
			parentOrSize[yRoot] = xRoot;
			return xRoot;
		}
	}

	boolean same(int x, int y) { // O(ﾎｱ(N))
		if(x < 0 || x >= num) throw new IndexOutOfBoundsException("x="+x);
		if(y < 0 || y >= num) throw new IndexOutOfBoundsException("y="+y);
		return root(x) == root(y);
	}

	int root(int x) { // O(ﾎｱ(N))
		if(parentOrSize[x] < 0) return x;
		parentOrSize[x] = root(parentOrSize[x]);
		return parentOrSize[x];
	}

	int size(int x) { // O(ﾎｱ(N))
		if(x < 0 || x >= num) throw new IndexOutOfBoundsException("x="+x);
		return - parentOrSize[root(x)];
	}


	HashMap<Integer, ArrayList<Integer>> groups() { // O(N)
		HashMap<Integer, ArrayList<Integer>> groups = new HashMap<>();
		for(int i = 0; i < num; i ++) {
			int root = root(i);
			if(!groups.containsKey(root)) groups.put(root, new ArrayList<>());
			groups.get(root).add(i);
		}
		return groups;
	}
}

