public void solve() {
	int num = ni();
	int query = ni();
	UnionFind uf = new UnionFind(num);
	for(int q = 0; q < query; q ++) {
		if(ni() == 0) uf.unite(ni(), ni());
		else prtln(uf.same(ni(), ni()) ? 1 : 0);
